def block_grid(grid, block=4, stride=5):
    """The (block x block) subgrids starting at multiples of stride, keyed by (row_index, col_index)."""
    P = list(range(0, block * block + 1, stride))[:block]
    return {(r // stride, c // stride): [[grid[r + dr][c + dc] for dc in range(block)] for dr in range(block)]
            for r in P for c in P}

def fill_from_template(grid, block=4, stride=5, filler=3, shape=2):
    """Erase filler-colored blocks; each block row gets shape-block copies where the template has a shape cell, and the cell at (block_row, block_col) of every block is recolored to 8."""
    g = [[0 if v == filler else v for v in row] for row in grid]
    bl = block_grid(g, block, stride)
    T = max(bl.values(), key=lambda b: sum(v == shape for r in b for v in r))
    out = [row[:] for row in g]
    for br, r in enumerate(range(0, block * block, stride)):
        for bc, c in enumerate(range(0, block * block, stride)):
            if T[br][bc] == shape and out[r][c] != shape:
                for dr in range(block):
                    for dc in range(block):
                        if T[dr][dc] == shape:
                            out[r + dr][c + dc] = shape
            if out[r + br][c + bc] == shape:
                out[r + br][c + bc] = 8
    return out
'''
